function createWorkTemplate() {
    const container = document.getElementById("work-container");

    works.forEach((work, index) => {
        const a = document.createElement("a");
        a.className = "work-link";
        a.href = work.href;
        // a.target = "_blank";

        if (index % 2 === 0) {
            a.classList.add("left");
        } else {
            a.classList.add("right");
        }
        

        const imageHtml = work.img ? `<img src="${work.img}" alt="${work.title}-img">` : `<p>No Image</p>`;

        a.innerHTML = `
            <section class="work-section">
                <h3>${work.title}</h3>
                ${imageHtml}
                <hr class="border-line">
                <div class="tech">
                    ${work.tech.map(t => icons[t]).join("")}
                </div>
            </section>
        `;

        container.appendChild(a);
    });
}

function adjustZigZag() {
    const items = document.querySelectorAll(".work-link");

    for (let i = 0; i < items.length - 1; i++) {
        const current = items[i];
        const next = items[i + 1];

        const height = current.offsetHeight;

        // 次の要素を上にずらす
        next.style.marginTop = `-${height / 4}px`;
    }
}

createWorkTemplate();
